use verus::prelude::*;

/// Computes by how many turns an attacker with given `strength`
/// will defeat an opponent with given `health`.
#[verifier::verus]
#[requires(health > 0 && strength > 0)]
#[ensures(result >= 0)]
#[ensures(result * (strength as i64) >= (health as i64))]
#[ensures((result - 1) * (strength as i64) < (health as i64))]
fn exec_turns_to_defeat(health: i8, strength: i8) -> i64 {
    // We cast to i64 so that intermediate arithmetic does not overflow.
    let h = health as i64;
    let s = strength as i64;
    // Standard “ceiling division”:
    (h + s - 1) / s
}

/// Determines whether Takahashi (who attacks first) will defeat Aoki.
/// Returns "Yes" if Takahashi can win in no more turns than Aoki needs to
/// defeat Takahashi; otherwise returns "No".
#[verifier::verus]
#[requires(a > 0 && b > 0 && c > 0 && d > 0)]
#[ensures(
    (exec_turns_to_defeat(c, b) <= exec_turns_to_defeat(a, d)) == (result == "Yes".to_string())
)]
fn solve(a: i8, b: i8, c: i8, d: i8) -> String {
    // Takahashi needs this many turns to defeat Aoki
    let turns_takahashi = exec_turns_to_defeat(c, b);
    // Aoki needs this many turns to defeat Takahashi
    let turns_aoki = exec_turns_to_defeat(a, d);

    if turns_takahashi <= turns_aoki {
        "Yes".to_string()
    } else {
        "No".to_string()
    }
}

